\begin{tikzpicture}[every node/.style={font=\large}, scale=0.8]
\draw[->] (0,0)--(0,6.4); \draw[->] (0,0)--(8.5,0); \foreach \y/\lab in {1/10,2/20,3/30,4/40,5/50} {\draw (-0.15,\y)--(0,\y); \node[left,font=\scriptsize] at (-0.15,\y) {$\lab$};} \node[left,font=\scriptsize] at (-0.15,0) {$0$};
